.layout {
  display: grid;
  grid-template-columns: 200px 1fr;
  /* two rows, two columns, named cells */
  grid-template-areas:
    "header header"
    "aside  main";
}

.layout > header { grid-area: header; }
.layout > aside  { grid-area: aside; }
.layout > main   { grid-area: main; }

.gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  /* fill rows, and let later items fill gaps */
  grid-auto-flow: row dense;
}
.gallery .wide { grid-column: span 2; }

.list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  /* each extra row is at least 120px and grows with content */
  grid-auto-rows: minmax(120px, auto);
  gap: 1rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.card {
  grid-column: span 2;
  display: grid;
  /* the card uses the two outer column lines */
  grid-template-columns: subgrid;
}

.cell {
  display: grid;
  grid-template-columns: 1fr;
}
.cell > button {
  /* horizontal placement inside the cell */
  justify-self: end;
}
/* in flexbox use margin-inline or justify-content instead */

.toolbar {
  display: flex;
  align-items: stretch;
}
.toolbar .icon {
  /* this item ignores the stretch and centres itself */
  align-self: center;
}

.cells {
  display: grid;
  grid-template-columns: repeat(3, 120px);
  /* every child centred in its cell unless it sets justify-self */
  justify-items: center;
}

.page {
  display: flex;
  flex-wrap: wrap;
  min-height: 100vh;
  /* pushes the wrapped rows to the top and bottom edges */
  align-content: space-between;
}

.toolbar {
  display: flex;
  /* direction first, then wrapping */
  flex-flow: row wrap;
  gap: 0.5rem;
}

.terms {
  /* at most three columns with gaps between them */
  column-count: 3;
  column-gap: 2rem;
}
@media (max-width: 600px) {
  .terms { column-count: 1; }
}

.terms {
  column-count: 2;
  column-gap: 2rem;
  /* the rule is centred in the gap */
  column-rule: 1px solid #d0d7de;
}

.card {
  /* width and height that still work in vertical writing mode */
  inline-size: 20rem;
  block-size: auto;
}
.vertical {
  writing-mode: vertical-rl;
  inline-size: 60vh; /* now the vertical extent */
}

.sheet {
  max-inline-size: 60rem;
  /* both inline margins, direction aware */
  margin-inline: auto;
}
.note {
  margin-block: 1rem 2rem; /* top and bottom */
}

.card-wrap {
  container-type: inline-size;
  container-name: card;
}

@container card (min-width: 30rem) {
  /* wide card: image beside the text */
  .card { display: grid; grid-template-columns: 8rem 1fr; }
}

@font-face {
  font-family: "Brand Sans";
  src: url("fonts/brand-sans.woff2") format("woff2");
  font-weight: 400 700;   /* range for a variable font */
  font-display: swap;     /* show fallback text first */
}

body {
  font-family: "Brand Sans", system-ui, sans-serif;
}

.cell-name {
  /* all three are needed, or no ellipsis appears */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 12rem;
}

.message {
  /* long tokens may break, normal words do not */
  overflow-wrap: anywhere;
}
.url {
  word-break: break-all; /* breaks anywhere, even mid word */
}

.hero-title {
  color: #fff;
  /* x, y, blur, colour; a dark halo keeps it readable on photos */
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.55);
}

.prose p { text-indent: 2rem; }

.hanging {
  /* pull the first line left, pad the wrapped lines */
  padding-left: 2rem;
  text-indent: -2rem;
}

em, .emphasis { font-style: italic; }

.pull-quote {
  /* slanted by 12 degrees where the font allows it */
  font-style: oblique 12deg;
}

.label {
  /* small caps usually need a little letter spacing */
  font-variant: small-caps;
  letter-spacing: 0.04em;
}
.price { font-variant-numeric: tabular-nums; }

a {
  text-decoration: underline;
  /* gap under the glyphs, and a heavier line */
  text-underline-offset: 0.2em;
  text-decoration-thickness: 2px;
}

.side-label {
  /* text runs top to bottom, lines stack right to left */
  writing-mode: vertical-rl;
  text-orientation: mixed;
}

.hyphenated {
  /* uses the dictionary that matches the lang attribute */
  hyphens: auto;
  max-width: 30ch;
}

pre, code {
  /* four space widths per tab, keeps pasted code aligned */
  tab-size: 4;
}
textarea { tab-size: 2; }

.badge {
  /* hue, saturation, lightness, then alpha after the slash */
  color: hsl(210 70% 40%);
  background: hsl(210 70% 40% / 0.12);
}
.badge--new { color: oklch(55% 0.16 250); }

.link {
  color: #0b5cad;
  /* border and icon follow the text colour */
  border-bottom: 2px solid currentColor;
}
.link:hover { color: #083f77; }

:root {
  /* native widgets may render dark when the system is dark */
  color-scheme: light dark;
}
@media (prefers-color-scheme: dark) {
  :root { --bg: #10141a; --fg: #e6edf3; }
}

/* one line instead of custom checkbox widgets */
input[type="checkbox"],
input[type="radio"],
input[type="range"] {
  accent-color: #1f6feb;
}

.overlay-title {
  /* dark text over a photo, blended with the pixels below */
  mix-blend-mode: multiply;
}
.hero::after {
  background: linear-gradient(90deg, #000, transparent);
  mix-blend-mode: screen;
}

.frame {
  border: 10px solid transparent;
  /* slice 1 stretches the gradient across the border */
  border-image: linear-gradient(135deg, #1f6feb, #6f42c1) 1;
}

.card:focus-visible {
  outline: 2px solid #1f6feb;
  /* space between the border and the ring */
  outline-offset: 3px;
}

.notice {
  border-width: 2px;
  /* top and bottom solid, left and right dashed */
  border-style: solid dashed;
  border-color: #b00020;
}

.hero {
  background-image: url("img/lobby.jpg");
  background-size: cover;
  /* the image stays put while the page scrolls */
  background-attachment: fixed;
}

.headline {
  background-image: linear-gradient(90deg, #1f6feb, #6f42c1);
  /* paint only inside the letters */
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.tinted {
  background-image: linear-gradient(#1f6feb, #1f6feb), url("img/room.jpg");
  background-size: cover;
  /* the gradient multiplies into the photo */
  background-blend-mode: multiply;
}

.pattern {
  background:
    url("img/dots.svg") repeat,             /* top layer */
    linear-gradient(180deg, #fff, #eef2f7); /* bottom layer */
  background-size: 24px, cover;
}

.sheet {
  position: fixed;
  inset: auto 0 0 0;
  background: rgba(255, 255, 255, 0.65); /* must be translucent */
  backdrop-filter: blur(8px) saturate(1.2);
}

.angled {
  /* the box still occupies the full rectangle */
  clip-path: polygon(0 0, 100% 0, 100% 85%, 0 100%);
}
.avatar { clip-path: circle(50%); }

.fade-bottom {
  /* opaque keeps, transparent hides */
  mask-image: linear-gradient(#000 60%, transparent);
  mask-repeat: no-repeat;
  mask-size: 100% 100%;
}

.table-head th {
  position: sticky;
  top: 0;           /* without this the element does not stick */
  background: #fff; /* rows would scroll under it */
  z-index: 1;
}

.overlay {
  position: absolute;
  /* top right bottom left, all zero */
  inset: 0;
}
.tooltip {
  position: absolute;
  inset: auto auto -0.5rem 50%; /* only bottom and left set */
}

/* starts fast, settles slowly, no bounce */
.panel {
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.panel.open { transform: translateY(0); }
.clock { transition: transform 1s steps(60); }

/* 240ms rise, 12px travel, played once */
@keyframes slide-up {
  from { transform: translateY(12px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.toast {
  animation: slide-up 240ms ease-out 1;
}
@media (prefers-reduced-motion: reduce) {
  .toast { animation: none; }
}

.toast {
  /* backwards applies the from state during the delay */
  animation: slide-up 240ms ease-out 200ms backwards;
}
.stays {
  animation-fill-mode: forwards; /* last frame held */
}

.dragging {
  /* set only while the interaction is likely */
  will-change: transform;
}
/* remove it when the drag ends, it is not a permanent optimisation */

/* smooth only when the user allows motion */
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

/* every slide snaps to the left edge */
.slider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
}
.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

section[id] {
  /* the sticky header is 4.5rem tall, keep the heading visible */
  scroll-margin-top: 5rem;
}

.scene {
  /* set on the parent, not on the transformed child */
  perspective: 800px;
  perspective-origin: 50% 50%;
}
.scene .card { transform: rotateY(20deg); }

/* the faces need a 3D context to flip in */
.flip-card {
  transform-style: preserve-3d;
  transition: transform 400ms;
}
.flip-card:hover { transform: rotateY(180deg); }

/* the back face stays invisible until rotated */
.face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
}
.back { transform: rotateY(180deg); }

@media print {
  nav, .no-print, form button { display: none; }
  body { color: #000; background: #fff; font-size: 11pt; }
  /* the address stays readable when the link text is not a URL */
  a::after { content: " (" attr(href) ")"; }
}

.booking-card {
  /* do not cut a card across two sheets */
  break-inside: avoid;
}
h2.new-chapter {
  break-before: page;
}

.status-badge {
  /* keep the colour instead of white boxes on paper */
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

button:focus-visible {
  outline: 2px solid #1f6feb;
  outline-offset: 2px;
}
/* never remove the ring without a replacement */
button:focus:not(:focus-visible) { outline: none; }

@media (forced-colors: active) {
  .card {
    /* system colours survive the forced palette */
    border: 1px solid CanvasText;
  }
  .card:focus-visible { outline: 2px solid Highlight; }
}

.sr-only {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
/* the text is still read aloud */

input, textarea {
  caret-color: #1f6feb;
  /* the selection highlight uses ::selection instead */
}

/* one rule for the page, one override for quotes */
::selection {
  background: #1f6feb;
  color: #fff;
}
.quote ::selection {
  background: #f2cc60;
  color: #000;
}

input::placeholder {
  color: #6b7280;
  /* Firefox reduces opacity on its own */
  opacity: 1;
}

/* bullets follow the brand colour */
li::marker {
  color: #1f6feb;
  font-weight: 700;
}
li.done::marker {
  content: "OK ";
}

body { counter-reset: section; }
h2 { counter-increment: section; }
h2::before {
  /* 1. , 2. , 3. before each heading */
  content: counter(section) ". ";
}
